import { useState, useEffect } from "react";
import axios from "axios";
import CompanyLayout from "./CompanyLayout";

const WILAYAS = ["Alger", "Oran", "Constantine", "Annaba", "Béjaïa", "Tizi Ouzou", "Blida", "Sétif", "Tlemcen", "Batna"];
const TYPES = ["On-site", "Remote", "Hybrid"];
const ALL_SKILLS = ["React", "Vue", "Angular", "Node.js", "Express", "Django", "FastAPI", "Laravel", "Python", "Java", "PHP", "C++", "SQL", "PostgreSQL", "MongoDB", "Docker", "Git", "Linux", "Flutter", "TypeScript"];

const EMPTY_FORM = {
    title: "",
    description: "",
    wilaya: "Alger",
    internship_type: "On-site",
    domain: "Web Development",
    duration: "6 months",
    skills: [],
    is_active: true,
};

// --- المودال ---
function OfferModal({ offer, onClose, onSave }) {
    const [form, setForm] = useState(offer ? { ...offer } : { ...EMPTY_FORM });
    
    const upd = (k, v) => setForm(f => ({ ...f, [k]: v }));
    const toggleSkill = s => setForm(f => ({ ...f, skills: f.skills.includes(s) ? f.skills.filter(x => x !== s) : [...f.skills, s] }));
    
    const isEdit = !!offer?.id;
    const valid = form.title.trim().length > 2 && form.description.trim().length > 10;

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={onClose}>
            <div className="bg-white p-6 rounded-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold text-xl mb-4">{isEdit ? "Edit offer" : "Post new offer"}</h3>
                <div className="space-y-4">
                    <input placeholder="Title" value={form.title} onChange={e => upd("title", e.target.value)} className="w-full p-2 border rounded" />
                    <textarea placeholder="Description" rows={4} value={form.description} onChange={e => upd("description", e.target.value)} className="w-full p-2 border rounded" />
                    <div className="grid grid-cols-2 gap-2">
                        <select value={form.wilaya} onChange={e => upd("wilaya", e.target.value)} className="p-2 border rounded">
                            {WILAYAS.map(w => <option key={w} value={w}>{w}</option>)}
                        </select>
                        <select value={form.internship_type} onChange={e => upd("internship_type", e.target.value)} className="p-2 border rounded">
                            {TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                        </select>
                    </div>
                    <div className="flex flex-wrap gap-1">
                        {ALL_SKILLS.map(s => (
                            <button key={s} onClick={() => toggleSkill(s)} className={`px-2 py-1 rounded text-xs ${form.skills.includes(s) ? "bg-olive-600 text-white" : "bg-slate-100"}`}>
                                {s}
                            </button>
                        ))}
                    </div>
                    <div className="flex gap-2 pt-4">
                        <button onClick={onClose} className="flex-1 py-2 border rounded">Cancel</button>
                        <button disabled={!valid} onClick={() => onSave(form)} className={`flex-1 py-2 rounded text-white ${valid ? "bg-olive-600" : "bg-slate-300"}`}>
                            {isEdit ? "Save" : "Post"}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

// --- المكون الرئيسي ---
export default function CompanyOffers() {
    const [offers, setOffers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState("all");
    const [modal, setModal] = useState(null);
    const [delModal, setDelModal] = useState(null);

    const API_URL = "http://127.0.0.1:8000/api/offers/";

    const getHeaders = () => {
        const userData = JSON.parse(localStorage.getItem("userData"));
        return { headers: { Authorization: `Bearer ${userData?.access}` } };
    };
    const fetchOffers = async () => {
        try {
            const res = await axios.get(API_URL, getHeaders());
            setOffers(res.data);
        } catch (err) {
            console.error("Fetch error:", err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { fetchOffers(); }, []);
    const handleSave = async (form) => {
            const token =localStorage 
          try {
            if (form.id) {
                const res = await axios.put(`${API_URL}${form.id}/`, form, getHeaders());
                setOffers(prev => prev.map(o => o.id === form.id ? res.data : o));
            } else {
                const res = await axios.post(API_URL, form, getHeaders());
                setOffers(prev => [res.data, ...prev]);
            }
            setModal(null);
        } catch (err) {
            alert("Error: " + JSON.stringify(err.response?.data));
        }
    };

    const handleDelete = async () => {
        try {
            await axios.delete(`${API_URL}${delModal.id}/`, getHeaders());
            setOffers(prev => prev.filter(o => o.id !== delModal.id));
            setDelModal(null);
        } catch (err) { alert("Delete failed"); }
    };

    const filtered = offers.filter(o => filter === "all" ? true : filter === "active" ? o.is_active : !o.is_active);

    return (
        <CompanyLayout active="offers">
            <div className="p-8 max-w-4xl mx-auto">
                <div className="flex justify-between mb-6">
                    <h1 className="text-2xl font-bold text-slate-900">Manage offers</h1>
                    <button onClick={() => setModal("create")} className="bg-olive-600 text-white px-4 py-2 rounded-xl">+ New offer</button>
                </div>

                <div className="space-y-4">
                    {loading ? <p>Loading...</p> : filtered.map(offer => (
                        <div key={offer.id} className="p-4 border rounded-2xl bg-white shadow-sm flex justify-between">
                            <div>
                                <h3 className="font-bold">{offer.title}</h3>
                                <p className="text-sm text-slate-500">{offer.wilaya} • {offer.internship_type}</p>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => setModal(offer)} className="p-2 border rounded">Edit</button>
                                <button onClick={() => setDelModal(offer)} className="p-2 border rounded text-red-500">🗑</button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
            {modal && <OfferModal offer={modal === "create" ? null : modal} onClose={() => setModal(null)} onSave={handleSave} />}
            {delModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                    <div className="bg-white p-6 rounded-2xl text-center">
                        <p className="mb-4">Delete "{delModal.title}"?</p>
                        <div className="flex gap-2">
                            <button onClick={() => setDelModal(null)} className="flex-1 p-2 border rounded">Cancel</button>
                            <button onClick={handleDelete} className="flex-1 bg-red-500 text-white p-2 rounded">Delete</button>
                        </div>
                    </div>
                </div>
            )}
        </CompanyLayout>
    );
}
